"use client"

import * as React from "react"

import { avatarToneVar, initialsFromName } from "../lib/df-avatar"
import {
  dfAvatarPresenceLabel,
  useDfStrings,
} from "../lib/df-intl"
import { sanitizeSrc } from "../lib/df-url"
import { cn } from "../lib/utils"

type AvatarSize = "xs" | "sm" | "md" | "lg"
type AvatarShape = "circle" | "square"
type AvatarPresence = "online" | "away" | "busy" | "offline"

type AvatarProps = Omit<React.HTMLAttributes<HTMLSpanElement>, "children"> & {
  name: string
  src?: string | null | undefined
  alt?: string | undefined
  size?: AvatarSize | undefined
  shape?: AvatarShape | undefined
  /** Presence indicator tone. Omit to hide the dot. */
  presence?: AvatarPresence | undefined
}

function cssUrl(value: string): string {
  return `url(${JSON.stringify(value)})`
}

function Avatar({
  className,
  name,
  src,
  alt,
  size = "md",
  shape = "circle",
  presence,
  style,
  "aria-label": ariaLabel,
  ...props
}: AvatarProps) {
  const s = useDfStrings()
  const [imageReady, setImageReady] = React.useState(false)
  const [loadedSrc, setLoadedSrc] = React.useState<string | null>(null)
  const [trackedSrc, setTrackedSrc] = React.useState(src)

  if (src !== trackedSrc) {
    setTrackedSrc(src)
    setLoadedSrc(null)
    setImageReady(false)
  }

  React.useEffect(() => {
    if (src == null || src === "") return
    const safeSrc = sanitizeSrc(src)
    if (safeSrc == null) return

    let cancelled = false
    const probe = new window.Image()
    probe.onload = () => {
      if (cancelled) return
      setLoadedSrc(safeSrc)
      setImageReady(true)
    }
    probe.onerror = () => {
      if (cancelled) return
      setLoadedSrc(null)
      setImageReady(false)
    }
    probe.src = safeSrc

    return () => {
      cancelled = true
      probe.onload = null
      probe.onerror = null
    }
  }, [src])

  const showImage = imageReady && loadedSrc != null
  const safeLoadedSrc =
    loadedSrc != null ? sanitizeSrc(loadedSrc) : null
  const initials = initialsFromName(name)
  const tone = avatarToneVar(name)

  return (
    <span
      data-df="avatar"
      data-size={size}
      data-shape={shape}
      data-presence={presence}
      className={cn(className)}
      style={
        {
          "--df-avatar-tone": tone,
          ...style,
        } as React.CSSProperties
      }
      title={props.title ?? name}
      aria-label={ariaLabel ?? alt ?? name}
      {...props}
    >
      {showImage && safeLoadedSrc != null ? (
        <span
          data-df="avatar-image"
          aria-hidden
          style={{ backgroundImage: cssUrl(safeLoadedSrc) }}
        />
      ) : (
        <span data-df="avatar-fallback" aria-hidden>
          {initials}
        </span>
      )}
      {presence != null ? (
        <span
          data-df="avatar-presence"
          data-tone={presence}
          aria-label={dfAvatarPresenceLabel(s, presence)}
        />
      ) : null}
    </span>
  )
}

type AvatarStackItem = {
  id: string
  name: string
  src?: string | null
  presence?: AvatarPresence
}

type AvatarStackProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> & {
  items: AvatarStackItem[]
  max?: number
  size?: AvatarSize
  shape?: AvatarShape
}

function AvatarStack({
  className,
  items,
  max = 3,
  size = "md",
  shape = "circle",
  ...props
}: AvatarStackProps) {
  const s = useDfStrings()
  const visible = items.slice(0, Math.max(0, max))
  const overflow = Math.max(0, items.length - visible.length)

  return (
    <div
      data-df="avatar-stack"
      data-size={size}
      className={cn(className)}
      {...props}
    >
      {visible.map((item) => (
        <Avatar
          key={item.id}
          name={item.name}
          src={item.src}
          presence={item.presence}
          size={size}
          shape={shape}
        />
      ))}
      {overflow > 0 ? (
        <span
          data-df="avatar-overflow"
          data-size={size}
          data-shape={shape}
          aria-label={s.avatarOverflowMore(overflow)}
        >
          {s.avatarOverflowVisible(overflow)}
        </span>
      ) : null}
    </div>
  )
}

export { Avatar, AvatarStack }
export type {
  AvatarPresence,
  AvatarProps,
  AvatarShape,
  AvatarSize,
  AvatarStackItem,
  AvatarStackProps,
}

/** Derive up to two initials from a display name. */
export function initialsFromName(name: string): string {
  const parts = name
    .trim()
    .split(/\s+/u)
    .filter((part) => part.length > 0)
  const firstPart = parts[0]
  if (firstPart === undefined) return "?"
  if (parts.length === 1) {
    return Array.from(firstPart).slice(0, 2).join("").toUpperCase()
  }
  const lastPart = parts[parts.length - 1]
  if (lastPart === undefined) return "?"
  const first = Array.from(firstPart)[0] ?? ""
  const last = Array.from(lastPart)[0] ?? ""
  return `${first}${last}`.toUpperCase()
}

/**
 * Mid tone kit scale steps used for initials avatars.
 * Values are CSS custom property names without the surrounding var().
 */
export const AVATAR_TONE_TOKENS = [
  "--df-blue-400",
  "--df-green-400",
  "--df-purple-400",
  "--df-orange-400",
  "--df-teal-400",
  "--df-rose-400",
  "--df-indigo-400",
  "--df-amber-400",
  "--df-cyan-400",
  "--df-violet-400",
  "--df-emerald-400",
  "--df-coral-400",
  "--df-fuchsia-400",
  "--df-jade-400",
  "--df-orchid-400",
  "--df-azure-400",
] as const

export type AvatarToneToken = (typeof AVATAR_TONE_TOKENS)[number]

/** Stable hash of a display name. Not for cryptography. */
export function hashName(name: string): number {
  let hash = 2166136261
  for (let i = 0; i < name.length; i++) {
    hash ^= name.charCodeAt(i)
    hash = Math.imul(hash, 16777619)
  }
  return hash >>> 0
}

/** Pick a deterministic kit tone token for a display name. */
export function avatarToneToken(name: string): AvatarToneToken {
  const index = hashName(name.trim() || "?") % AVATAR_TONE_TOKENS.length
  return AVATAR_TONE_TOKENS[index]!
}

/** CSS `var(--…)` reference for the hashed avatar tone. */
export function avatarToneVar(name: string): string {
  return `var(${avatarToneToken(name)})`
}

const BLOCKED_SCHEMES = /^(javascript|data|vbscript):/i

function hasControlCharacter(value: string): boolean {
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i)
    if (code <= 0x1f || code === 0x7f) return true
  }
  return false
}

/**
 * Validate a link href for the editor model.
 * Allows http, https, mailto, and relative paths. Rejects javascript and data schemes.
 */
export function isSafeHref(href: string): boolean {
  const value = href.trim()
  if (!value) return false
  if (BLOCKED_SCHEMES.test(value)) return false
  if (hasControlCharacter(value)) return false

  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(value)
  if (!schemeMatch) {
    // Relative, hash, or protocol relative looking without scheme token.
    if (value.startsWith("//")) return false
    return true
  }

  const scheme = schemeMatch[1]!.toLowerCase()
  return scheme === "http" || scheme === "https" || scheme === "mailto"
}

/** Return a safe href, or null when the value must not be stored or rendered as a link. */
export function sanitizeHref(href: string): string | null {
  const trimmed = href.trim()
  if (!isSafeHref(trimmed)) return null
  return trimmed
}

const DATA_IMAGE_MIME = /^data:(image\/[a-z0-9.+-]+)(;|,)/i

/**
 * Validate an image src for avatar and uploader previews.
 * Allows http, https, blob, data:image except svg+xml, and same-origin relative paths.
 */
export function sanitizeSrc(src: string): string | null {
  const value = src.trim()
  if (!value) return null
  if (hasControlCharacter(value)) return null
  if (value.startsWith("//")) return null

  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(value)
  if (!schemeMatch) {
    return value
  }

  const scheme = schemeMatch[1]!.toLowerCase()
  if (scheme === "http" || scheme === "https" || scheme === "blob") {
    return value
  }

  if (scheme === "data") {
    const mimeMatch = DATA_IMAGE_MIME.exec(value)
    if (!mimeMatch) return null
    const mime = mimeMatch[1]!.toLowerCase()
    if (mime === "image/svg+xml") return null
    return value
  }

  return null
}
